import{_ as l,a0 as p,w as o,s as d,ao as h,I as t,x as i,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"為初學者提供的 uniq 命令教程及示例 | LCTT x X-CMD","titleTemplate":false,"description":"為初學者提供的 uniq 命令教程及示例 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為初學者提供的 uniq 命令教程及示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為初學者提供的 uniq 命令教程及示例 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180102 The Uniq Command Tutorial With Examples For Beginners","title":"為初學者提供的 uniq 命令教程及示例","tag":"201804","desc":""},"relativePath":"201804/20180102 The Uniq Command Tutorial With Examples For Beginners.md","filePath":"[post].md"}'),r={name:"201804/20180102 The Uniq Command Tutorial With Examples For Beginners.md"};function c(g,s,u,k,b,x){const e=p("Link");return o(),d("div",null,[s[13]||(s[13]=h(`<h1 id="為初學者提供的-uniq-命令教程及示例" tabindex="-1">為初學者提供的 uniq 命令教程及示例 <a class="header-anchor" href="#為初學者提供的-uniq-命令教程及示例" aria-label="Permalink to “為初學者提供的 uniq 命令教程及示例”">​</a></h1><p>如果你主要是在命令列上工作，並且每天處理大量的文本文件，那麼你應該瞭解下 <code>uniq</code> 命令。該命令會幫助你輕鬆地從文件中找到重複的行。它不僅用於查找重複項，而且我們還可以使用它來刪除重複項，顯示重複項的出現次數，只顯示重複的行，只顯示唯一的行等。由於 <code>uniq</code> 命令是 GNU coreutils 包的一部分，所以它預裝在大多數 Linux 發行版中，讓我們不需要費心安裝。來看一些實際的例子。</p><p>請注意，除非重複行是相鄰的，否則 <code>uniq</code> 不會刪除它們。因此，你可能需要先對它們進行排序，或將排序命令與 <code>uniq</code> 組合以獲得結果。讓我給你看一些例子。</p><p>首先，讓我們創建一個帶有一些重複行的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi ostechnix.txt</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>welcome to ostechnix</span></span>
<span class="line"><span>welcome to ostechnix</span></span>
<span class="line"><span>Linus is the creator of Linux.</span></span>
<span class="line"><span>Linux is secure by default</span></span>
<span class="line"><span>Linus is the creator of Linux.</span></span>
<span class="line"><span>Top 500 super computers are powered by Linux</span></span></code></pre></div><p>正如你在上面的文件中看到的，我們有一些重複的行（第一行和第二行，第三行和第五行是重複的）。</p><h3 id="_1、-使用-uniq-命令刪除文件中的連續重複行" tabindex="-1">1、 使用 uniq 命令刪除文件中的連續重複行 <a class="header-anchor" href="#_1、-使用-uniq-命令刪除文件中的連續重複行" aria-label="Permalink to “1、 使用 uniq 命令刪除文件中的連續重複行”">​</a></h3><p>如果你在不使用任何參數的情況下使用 <code>uniq</code> 命令，它將刪除所有連續的重複行，只顯示唯一的行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uniq ostechnix.txt</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/uniq-2.png" alt=""></p><p>如你所見， <code>uniq</code> 命令刪除了給定文件中的所有連續重複行。你可能還注意到，上面的輸出仍然有第二行和第四行重複了。這是因為 <code>uniq</code> 命令只有在相鄰的情況下才會刪除重複的行，當然，我們也可以刪除非連續的重複行。請看下面的第二個例子。</p><h3 id="_2、-刪除所有重複的行" tabindex="-1">2、 刪除所有重複的行 <a class="header-anchor" href="#_2、-刪除所有重複的行" aria-label="Permalink to “2、 刪除所有重複的行”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/uniq-1-1.png" alt=""></p><p>看到了嗎？沒有重複的行。換句話説，上面的命令將顯示在 <code>ostechnix.txt</code> 中只出現一次的行。我們使用 <code>sort</code> 命令與 <code>uniq</code> 命令結合，因為，就像我提到的，除非重複行是相鄰的，否則 <code>uniq</code> 不會刪除它們。</p><h3 id="_3、-只顯示文件中唯一的一行" tabindex="-1">3、 只顯示文件中唯一的一行 <a class="header-anchor" href="#_3、-只顯示文件中唯一的一行" aria-label="Permalink to “3、 只顯示文件中唯一的一行”">​</a></h3><p>為了只顯示文件中唯一的一行，可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -u</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux is secure by default</span></span>
<span class="line"><span>Top 500 super computers are powered by Linux</span></span></code></pre></div><p>如你所見，在給定的文件中只有兩行是唯一的。</p><h3 id="_4、-只顯示重複的行" tabindex="-1">4、 只顯示重複的行 <a class="header-anchor" href="#_4、-只顯示重複的行" aria-label="Permalink to “4、 只顯示重複的行”">​</a></h3><p>同樣的，我們也可以顯示文件中重複的行，就像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -d</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linus is the creator of Linux.</span></span>
<span class="line"><span>welcome to ostechnix</span></span></code></pre></div><p>這兩行在 <code>ostechnix.txt</code> 文件中是重複的行。請注意 <code>-d</code>（小寫 <code>d</code>） 將會只打印重複的行，每組顯示一個。打印所有重複的行，使用 <code>-D</code>（大寫 <code>D</code>），如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -D</span></span></code></pre></div><p>在下面的截圖中看兩個選項的區別：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/uniq-4.png" alt=""></p><h3 id="_5、-顯示文件中每一行的出現次數" tabindex="-1">5、 顯示文件中每一行的出現次數 <a class="header-anchor" href="#_5、-顯示文件中每一行的出現次數" aria-label="Permalink to “5、 顯示文件中每一行的出現次數”">​</a></h3><p>由於某種原因，你可能想要檢查給定文件中每一行重複出現的次數。要做到這一點，使用 <code>-c</code> 選項，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -c</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 2 Linus is the creator of Linux.</span></span>
<span class="line"><span> 1 Linux is secure by default</span></span>
<span class="line"><span> 1 Top 500 super computers are powered by Linux</span></span>
<span class="line"><span> 2 welcome to ostechnix</span></span></code></pre></div><p>我們還可以按照每一行的出現次數進行排序，然後顯示，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -c | sort -nr</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 2 welcome to ostechnix</span></span>
<span class="line"><span> 2 Linus is the creator of Linux.</span></span>
<span class="line"><span> 1 Top 500 super computers are powered by Linux</span></span>
<span class="line"><span> 1 Linux is secure by default</span></span></code></pre></div><h3 id="_6、-將比較限制為-n-個字符" tabindex="-1">6、 將比較限制為 N 個字符 <a class="header-anchor" href="#_6、-將比較限制為-n-個字符" aria-label="Permalink to “6、 將比較限制為 N 個字符”">​</a></h3><p>我們可以使用 <code>-w</code> 選項來限制對文件中特定數量字符的比較。例如，讓我們比較文件中的前四個字符，並顯示重複行，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uniq -d -w 4 ostechnix.txt</span></span></code></pre></div><h3 id="_7、-忽略比較指定的-n-個字符" tabindex="-1">7、 忽略比較指定的 N 個字符 <a class="header-anchor" href="#_7、-忽略比較指定的-n-個字符" aria-label="Permalink to “7、 忽略比較指定的 N 個字符”">​</a></h3><p>像對文件中行的前 N 個字符進行限制比較一樣，我們也可以使用 <code>-s</code> 選項來忽略比較前 N 個字符。</p><p>下面的命令將忽略在文件中每行的前四個字符進行比較：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uniq -d -s 4 ostechnix.txt</span></span></code></pre></div><p>為了忽略比較前 N 個字段（LCTT 譯註：即前幾列）而不是字符，在上面的命令中使用 <code>-f</code> 選項。</p><p>欲瞭解更多詳情，請參考幫助部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uniq --help</span></span></code></pre></div><p>也可以使用 <code>man</code> 命令查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man uniq</span></span></code></pre></div><p>今天就到這裏！我希望你現在對 <code>uniq</code> 命令及其目的有一個基本的瞭解。如果你發現我們的指南有用，請在你的社交網絡上分享，並繼續支持我們。更多好東西要來了，請繼續關注！</p><p>乾杯！</p><hr>`,57)),t("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/uniq-command-tutorial-examples-beginners/"},{default:n(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/uniq-command-tutorial-examples-beginners/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com"},{default:n(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),a(e,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[3]||(s[3]=[i("MjSeven",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const C=l(r,[["render",c]]);export{y as __pageData,C as default};
